24	import java.time.LocalDate;
25	import java.time.Period;
26	import java.time.temporal.ChronoUnit;
27	import java.util.*;
28	
29	/**
30	 * Simple JavaBean domain object representing an owner.
31	 *
32	 * @author Ken Krebs
33	 * @author Juergen Hoeller
34	 * @author Sam Brannen
35	 * @author Michael Isvy
36	 */
37	@Entity
38	@Table(name = "owners")
39	public class Owner extends Person {
40	    @Column(name = "address")
41	    @NotEmpty
42	    private String address;
43	
44	    @Column(name = "city")
45	    @NotEmpty
46	    private String city;
47	
48	    @Column(name = "telephone")
49	    @NotEmpty
50	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Phone number must be in E.164 format")
51	    private String telephone;
52	
53	    @Column(name = "email")
54	    private String email;
55	
56	    @Column(name = "registration_date", columnDefinition = "DATE")
57	    private LocalDate registrationDate;
58	
59	    @Column(name = "birth_date", columnDefinition = "DATE")
60	    private LocalDate birthDate;
61	
62	    @Column(name = "customer_code")
63	    private String customerCode;
64	
65	    @Column(name = "household_id")
66	    private String householdId;
67	
68	    @Column(name = "namesake_count")
69	    private Integer namesakeCount;
70	
71	    @Column(name = "household_size")
72	    private Integer householdSize;
73	
74	    @Column(name = "bulk_signup_warning")
75	    private Boolean bulkSignupWarning;
76	
77	    @Column(name = "postcode")
78	    private String postcode;
79	
80	    @Column(name = "possible_duplicate")
81	    private Boolean possibleDuplicate;
82	
83	    @Column(name = "possible_duplicate_of")
84	    private Integer possibleDuplicateOf;
85	
86	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
87	    private Set<Pet> pets;
88	
89	    public String getAddress() {
90	        return this.address;
91	    }
92	
93	    public void setAddress(String address) {
94	        this.address = address;
95	    }
96	
97	    public String getCity() {
98	        return this.city;
99	    }
100	
101	    public void setCity(String city) {
102	        this.city = city;
103	    }
104	
105	    public String getTelephone() {
106	        return this.telephone;
107	    }
108	
109	    public void setTelephone(String telephone) {
110	        this.telephone = telephone;
111	    }
112	
113	    public String getEmail() {
114	        return this.email;
115	    }
116	
117	    public void setEmail(String email) {
118	        this.email = email;
119	    }
120	
121	    public LocalDate getRegistrationDate() {
122	        return this.registrationDate;
123	    }
124	
125	    public void setRegistrationDate(LocalDate registrationDate) {
126	        this.registrationDate = registrationDate;
127	    }
128	
129	    public LocalDate getBirthDate() {
130	        return this.birthDate;
131	    }
132	
133	    public void setBirthDate(LocalDate birthDate) {
134	        this.birthDate = birthDate;
135	    }
136	
137	    /**
138	     * The owner's age band derived from {@link #birthDate}, computed against the
139	     * {@link #registrationDate}: {@code "MINOR"} when under 18, {@code "ADULT"} when
140	     * 18 to 64 inclusive, {@code "SENIOR"} when 65 or over. Null when either the birth
141	     * date or the registration date is absent.
142	     */
143	    @Transient
144	    public String getAgeBand() {
145	        if (this.birthDate == null || this.registrationDate == null) {
146	            return null;
147	        }
148	        int age = Period.between(this.birthDate, this.registrationDate).getYears();
149	        if (age < 18) {
150	            return "MINOR";
151	        }
152	        if (age < 65) {
153	            return "ADULT";
154	        }
155	        return "SENIOR";
156	    }
157	
158	    public String getCustomerCode() {
159	        return this.customerCode;
160	    }
161	
162	    public void setCustomerCode(String customerCode) {
163	        this.customerCode = customerCode;
164	    }
165	
166	    public String getHouseholdId() {
167	        return this.householdId;
168	    }
169	
170	    public void setHouseholdId(String householdId) {
171	        this.householdId = householdId;
172	    }
173	
174	    public Integer getNamesakeCount() {
175	        return this.namesakeCount;
176	    }
177	
178	    public void setNamesakeCount(Integer namesakeCount) {
179	        this.namesakeCount = namesakeCount;
180	    }
181	
182	    public Integer getHouseholdSize() {
183	        return this.householdSize;
184	    }
185	
186	    public void setHouseholdSize(Integer householdSize) {
187	        this.householdSize = householdSize;
188	    }
189	
190	    public Boolean getBulkSignupWarning() {
191	        return this.bulkSignupWarning;
192	    }
193	
194	    public void setBulkSignupWarning(Boolean bulkSignupWarning) {
195	        this.bulkSignupWarning = bulkSignupWarning;
196	    }
197	
198	    public String getPostcode() {
199	        return this.postcode;
200	    }
201	
202	    public void setPostcode(String postcode) {
203	        this.postcode = postcode;
204	    }
205	
206	    public Boolean getPossibleDuplicate() {
207	        return this.possibleDuplicate;
208	    }
209	
210	    public void setPossibleDuplicate(Boolean possibleDuplicate) {
211	        this.possibleDuplicate = possibleDuplicate;
212	    }
213	
214	    public Integer getPossibleDuplicateOf() {
215	        return this.possibleDuplicateOf;
216	    }
217	
218	    public void setPossibleDuplicateOf(Integer possibleDuplicateOf) {
219	        this.possibleDuplicateOf = possibleDuplicateOf;
220	    }
221	
222	    /**
223	     * The owner's name formatted for display as {@code "LastName, FirstName"}.
224	     */
225	    @Transient
226	    public String getDisplayName() {
227	        return this.getLastName() + ", " + this.getFirstName();
228	    }
229	
230	    /**
231	     * The owner's initials: the upper-cased first letters of firstName and
232	     * lastName, dot-separated with a trailing dot (e.g. {@code "J.S."}).
233	     */
234	    @Transient
235	    public String getInitials() {
236	        return Character.toUpperCase(this.getFirstName().charAt(0)) + "."
237	            + Character.toUpperCase(this.getLastName().charAt(0)) + ".";
238	    }
239	
240	    /**
241	     * The owner's membership number, formatted {@code "<customerCode>-M<YY>"} where
242	     * YY is the last two digits of the registration date's year
243	     * (e.g. {@code "NSW-A1B2C3D4-M26"}). Derived from the owner's own fields; null when
244	     * either the customer code or registration date is absent.
245	     */
246	    @Transient
247	    public String getMembershipNumber() {
248	        if (this.customerCode == null || this.registrationDate == null) {
249	            return null;
250	        }
251	        return String.format("%s-M%02d", this.customerCode, this.registrationDate.getYear() % 100);
252	    }
253	
254	    /**
255	     * The owner's check digit: a single Luhn check digit (0-9) computed over the digits
256	     * contained in the {@code customerCode}, scanning right to left and doubling the
257	     * rightmost digit first; non-digit characters are ignored. Derived from the owner's
258	     * own fields; null when the customer code is absent.
259	     */
260	    @Transient
261	    public Integer getCheckDigit() {
262	        if (this.customerCode == null) {
263	            return null;
264	        }
265	        int sum = 0;
266	        boolean dbl = true;
267	        for (int i = this.customerCode.length() - 1; i >= 0; i--) {
268	            char c = this.customerCode.charAt(i);
269	            if (c < '0' || c > '9') {
270	                continue;
271	            }
272	            int d = c - '0';
273	            if (dbl) {
274	                d *= 2;
275	                if (d > 9) {
276	                    d -= 9;
277	                }
278	            }
279	            sum += d;
280	            dbl = !dbl;
281	        }
282	        return (10 - (sum % 10)) % 10;
283	    }
284	
285	    /**
286	     * The owner's membership points: a running score built from the owner's own fields.
287	     * Starts at 0 and gains 2 when an email address is present, a further 1 when the owner
288	     * has no namesakes ({@code namesakeCount} is 0), a further 2 when it belongs to a
289	     * household of 3 or more members ({@code householdSize} is 3 or more), and a further 3
290	     * for tenure of more than 365 days (the days from {@link #registrationDate} to the
291	     * current date). A newly created owner has zero tenure, so the pre-tenure factors alone
292	     * top out at 5 points. Derived from the owner's own fields.
293	     */
294	    @Transient
295	    public Integer getMembershipPoints() {
296	        int points = 0;
297	        boolean hasEmail = this.email != null && !this.email.isBlank();
298	        if (hasEmail) {
299	            points += 2;
300	        }
301	        boolean unique = this.namesakeCount != null && this.namesakeCount == 0;
302	        if (unique) {
303	            points += 1;
304	        }
305	        boolean largeHousehold = this.householdSize != null && this.householdSize >= 3;
306	        if (largeHousehold) {
307	            points += 2;
308	        }
309	        boolean tenured = this.registrationDate != null
310	            && ChronoUnit.DAYS.between(this.registrationDate, LocalDate.now()) > 365;
311	        if (tenured) {
312	            points += 3;
313	        }
314	        return points;
315	    }
316	
317	    /**
318	     * The owner's membership level: a number from 1 to 4 derived by banding
319	     * {@link #getMembershipPoints()} — 1 for 0-1 points, 2 for 2-3, 3 for 4-5 and 4 for 6
320	     * or more. Derived from the owner's own fields.
321	     */
322	    @Transient
323	    public Integer getMembershipLevel() {
324	        int points = getMembershipPoints();
325	        if (points <= 1) {
326	            return 1;
327	        }
328	        if (points <= 3) {
329	            return 2;
330	        }
331	        if (points <= 5) {
332	            return 3;
333	        }
334	        return 4;
335	    }
336	
337	    /**
338	     * Fixed city-to-region lookup table. Any city not listed derives locality
339	     * {@code "UNKNOWN"}.
340	     */
341	    private static final Map<String, String> CITY_REGION = Map.of(
342	        "Sydney", "NSW",
343	        "Melbourne", "VIC",
344	        "Brisbane", "QLD");
345	
346	    /**
347	     * Region -> inclusive 4-digit postcode range {low, high}: NSW 2000-2099,
348	     * VIC 3000-3099, QLD 4000-4099. The single source of truth for the
349	     * postcode-to-region mapping, consulted by {@link #regionForPostcode(String)}
350	     * (used by locality derivation) and {@link #hasPostcodeRange(String)} (used by
351	     * postcode validation).
352	     */
353	    private static final Map<String, int[]> REGION_POSTCODE_RANGES = Map.of(
354	        "NSW", new int[] {2000, 2099},
355	        "VIC", new int[] {3000, 3099},
356	        "QLD", new int[] {4000, 4099});
357	
358	    /**
359	     * The owner's locality: the REGION component of the owner's region-and-hash identity.
360	     * Read off the {@code customerCode} prefix (the part before the first {@code '-'}) when
361	     * a customer code is present, otherwise derived straight from the postcode via
362	     * {@link #identityRegion(String)}. Either way this yields the region the customer code
363	     * was built from — NSW/VIC/QLD, or {@code "UNKNOWN"} when the postcode is absent or in
364	     * no known range. Derived from the owner's own fields.
365	     */
366	    @Transient
367	    public String getLocality() {
368	        if (this.customerCode != null) {
369	            int dash = this.customerCode.indexOf('-');
370	            if (dash > 0) {
371	                return this.customerCode.substring(0, dash);
372	            }
373	        }
374	        return identityRegion(this.postcode);
375	    }
376	
377	    /**
378	     * The REGION component of an owner's region-and-hash identity: the region derived from
379	     * the postcode via {@link #regionForPostcode(String)} (NSW/VIC/QLD), or
380	     * {@code "UNKNOWN"} when the postcode is absent or in no known range. The single source
381	     * of truth for the identity's region, so the {@code customerCode} prefix and the
382	     * {@link #getLocality() locality} cannot drift apart.
383	     */
384	    public static String identityRegion(String postcode) {
385	        String region = regionForPostcode(postcode);
386	        return region != null ? region : "UNKNOWN";
387	    }
388	
389	    /**
390	     * The canonical region for a city per the fixed city-to-region table
391	     * ({@code Sydney->NSW}, {@code Melbourne->VIC}, {@code Brisbane->QLD}), or
392	     * {@code "UNKNOWN"} when the city is not in the table. The single source of truth
393	     * for the city-to-region mapping, used as the city's region in postcode validation.
394	     */
395	    public static String regionForCity(String city) {
396	        return CITY_REGION.getOrDefault(city, "UNKNOWN");
397	    }
398	
399	    /**
400	     * The canonical region for a 4-digit postcode per the fixed range table
401	     * (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099), or {@code null} when the postcode
402	     * is absent, not a well-formed integer, or in no known range. Reads the shared
403	     * {@link #REGION_POSTCODE_RANGES} table; used by {@link #identityRegion(String)}
404	     * for the identity's region and by postcode validation to range-check a submitted
405	     * postcode against its city's region.
406	     */
407	    public static String regionForPostcode(String postcode) {
408	        if (postcode == null) {
409	            return null;
410	        }
411	        int value;
412	        try {
413	            value = Integer.parseInt(postcode.trim());
414	        } catch (NumberFormatException ex) {
415	            return null;
416	        }
417	        for (Map.Entry<String, int[]> entry : REGION_POSTCODE_RANGES.entrySet()) {
418	            int[] range = entry.getValue();
419	            if (value >= range[0] && value <= range[1]) {
420	                return entry.getKey();
421	            }
422	        }
423	        return null;
424	    }
425	
426	    /**
427	     * Whether the region is subject to postcode range validation, i.e. has a known
428	     * range in the shared {@link #REGION_POSTCODE_RANGES} table. A region with no range
429	     * (including {@code "UNKNOWN"}) accepts any well-formed postcode.
430	     */
431	    public static boolean hasPostcodeRange(String region) {
432	        return REGION_POSTCODE_RANGES.containsKey(region);
433	    }
434	
435	    /**
436	     * The owner's preferred contact channel: {@code "EMAIL"} when an email address is
437	     * present, otherwise {@code "PHONE"}. Derived from the owner's own fields.
438	     */
439	    @Transient
440	    public String getContactPreference() {
441	        boolean hasEmail = this.email != null && !this.email.isBlank();
442	        return hasEmail ? "EMAIL" : "PHONE";
443	    }
444	
445	    /**
446	     * The owner's identity key: a display-only composite value formed as
447	     * {@code normalizedTelephone + "|" + (email or empty) + "|" + (householdId or empty)}.
448	     * The telephone and email are already stored in their normalized forms (E.164 and
449	     * lower-cased), and the household id is derived from the last name and postcode (empty
450	     * for an owner with no postcode). It drives no logic — duplicate detection is keyed on
451	     * the household (same last name and postcode); this value is exposed on the API purely
452	     * for reference. A null or blank part contributes an empty segment. Derived from the
453	     * owner's own fields.
454	     */
455	    @Transient
456	    public String getIdentityKey() {
457	        return keyPart(this.telephone) + "|" + keyPart(this.email) + "|" + keyPart(this.householdId);
458	    }
459	
460	    private static String keyPart(String value) {
461	        return (value == null || value.isBlank()) ? "" : value;
462	    }
463	
464	    /**
465	     * The stored E.164 {@link #telephone} formatted for humans: the country code,
466	     * a space, then the national digits grouped in threes (e.g.
467	     * {@code "+61 412 345 678"}). The {@code '+'} and country code are taken from the
468	     * E.164 value (a {@code '+1'} NANP country code is a single digit, any other is
469	     * treated as two digits, matching the recognized {@code '+61'}/{@code '+1'} forms),
470	     * and the national digits follow in space-separated groups of three. Returns the raw
471	     * value unchanged when it is absent or not a {@code '+'}-prefixed run of digits.
472	     * Derived from the owner's own fields; the raw {@link #telephone} stays E.164.
473	     */
474	    @Transient
475	    public String getTelephoneDisplay() {
476	        if (this.telephone == null || !this.telephone.startsWith("+")) {
477	            return this.telephone;
478	        }
479	        String digits = this.telephone.substring(1);
480	        if (!digits.matches("\\d+")) {
481	            return this.telephone;
482	        }
483	        int countryCodeLength = digits.startsWith("1") ? 1 : 2;
484	        if (digits.length() <= countryCodeLength) {
485	            return this.telephone;
486	        }
487	        String countryCode = digits.substring(0, countryCodeLength);
488	        String national = digits.substring(countryCodeLength);
