3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	
7	/**
8	 * Assigns the owner's {@code namesakeCount}: the number of existing owners that share
9	 * the same first name and last name, compared case-insensitively. Runs before the owner
10	 * is saved, so the count reflects the existing owners only (not the owner being created).
11	 */
12	public class CountNamesakes {
13	
14	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
15	        String firstName = OwnerNames.normalize(owner.getFirstName());
16	        String lastName = OwnerNames.normalize(owner.getLastName());
17	        int count = 0;
18	        for (Owner existing : ownerRepository.findAll()) {
19	            if (firstName.equals(OwnerNames.normalize(existing.getFirstName()))
20	                    && lastName.equals(OwnerNames.normalize(existing.getLastName()))) {
21	                count++;
22	            }
23	        }
24	        owner.setNamesakeCount(count);
25	    }
26	}
